-- 2NF Compliant Schema Decomposition
CREATE TABLE products (
    product_id INT PRIMARY KEY,
    product_name VARCHAR(100) NOT NULL,
    list_price NUMERIC(10, 2) NOT NULL
);

CREATE TABLE order_items (
    order_id INT NOT NULL,
    product_id INT NOT NULL,
    quantity INT NOT NULL,
    PRIMARY KEY (order_id, product_id),
    FOREIGN KEY (product_id) REFERENCES products(product_id)
);

-- 3NF Compliant Schema Decomposition
CREATE TABLE customers (
    customer_id INT PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    city VARCHAR(100) NOT NULL
);

CREATE TABLE orders (
    order_id INT PRIMARY KEY,
    customer_id INT NOT NULL REFERENCES customers(customer_id),
    order_date DATE NOT NULL
);

-- BCNF Decomposition of overlapping candidate keys
CREATE TABLE professor_specialties (
    professor_id INT PRIMARY KEY,
    subject_code VARCHAR(20) NOT NULL
);

CREATE TABLE student_advisors (
    student_id INT NOT NULL,
    professor_id INT NOT NULL REFERENCES professor_specialties(professor_id),
    PRIMARY KEY (student_id, professor_id)
);

-- Non-Repeatable Read under Read Committed:
BEGIN;
SELECT balance FROM accounts WHERE id = 1; -- Sees $100
-- Concurrent session commits: UPDATE accounts SET balance = 500 WHERE id = 1;
SELECT balance FROM accounts WHERE id = 1; -- Sees $500!
COMMIT;

-- Preventing Write Skew under SERIALIZABLE
BEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE;
SELECT COUNT(*) FROM on_call_doctors; -- Invariant: at least 1 must remain
UPDATE on_call_doctors SET active = false WHERE doctor_id = 'Alice';
COMMIT; -- Engine aborts with 40001 if Bob took off-call concurrently!

-- NON-SARGABLE:
-- SELECT * FROM users WHERE created_at + INTERVAL '7 days' > NOW();

-- SARGABLE REWRITE:
SELECT * FROM users WHERE created_at > NOW() - INTERVAL '7 days';

-- Inspecting statistics in catalogs
SELECT attname, n_distinct, most_common_vals, histogram_bounds 
FROM pg_stats WHERE tablename = 'orders';

-- Cascade vs Restrict
CREATE TABLE orders (order_id INT PRIMARY KEY);
CREATE TABLE order_items (
    order_id INT REFERENCES orders(order_id) ON DELETE CASCADE,
    item_id INT,
    PRIMARY KEY (order_id, item_id)
);

-- Parameterized query in Node.js (Immune to injection)
const query = 'SELECT id, email FROM users WHERE email = $1';
const result = await db.query(query, [userInput]);

-- Column-level security
GRANT SELECT (id, name, email) ON users TO customer_support_role;
REVOKE ALL ON user_salaries FROM customer_support_role;
